import team.creative.playerrevive.client.ReviveEventClient;
import team.creative.playerrevive.packet.GiveUpPacket;
import team.creative.playerrevive.packet.HelperPacket;
import team.creative.playerrevive.packet.ReviveUpdatePacket;
import team.creative.playerrevive.server.PlayerReviveServer;
import team.creative.playerrevive.server.ReviveEventServer;

@Mod(PlayerRevive.MODID)
public class PlayerRevive {

    public static final Logger LOGGER = LogManager.getLogger(PlayerRevive.MODID);
    public static final String MODID = "playerrevive";
    public static PlayerReviveConfig CONFIG;
    public static final CreativeNetwork NETWORK = new CreativeNetwork(1, LOGGER, new ResourceLocation(PlayerRevive.MODID, "main"));

    public static final ResourceLocation BLEEDING_NAME = new ResourceLocation(MODID, "bleeding");
    public static final ResourceKey<DamageType> BLED_TO_DEATH = ResourceKey.create(Registries.DAMAGE_TYPE, new ResourceLocation(MODID, "bled_to_death"));

    public static final SoundEvent DEATH_SOUND = SoundEvent.createVariableRangeEvent(new ResourceLocation(MODID, "death"));
    public static final SoundEvent REVIVED_SOUND = SoundEvent.createVariableRangeEvent(new ResourceLocation(MODID, "revived"));

    public static final Capability<IBleeding> BLEEDING = CapabilityManager.get(new CapabilityToken<>() {});

    public void register(RegisterEvent event) {
        event.register(Keys.SOUND_EVENTS, x -> {
            x.register(new ResourceLocation(MODID, "death"), DEATH_SOUND);
            x.register(new ResourceLocation(MODID, "revived"), REVIVED_SOUND);
        });
    }

    public PlayerRevive() {
        DistExecutor.unsafeRunWhenOn(Dist.CLIENT, () -> () -> FMLJavaModLoadingContext.get().getModEventBus().addListener(this::client));
        FMLJavaModLoadingContext.get().getModEventBus().addListener(this::init);
        FMLJavaModLoadingContext.get().getModEventBus().addListener(this::register);
        MinecraftForge.EVENT_BUS.addListener(this::serverStarting);
        FMLJavaModLoadingContext.get().getModEventBus().addListener(this::registerCaps);
    }

    @OnlyIn(value = Dist.CLIENT)
    private void client(final FMLClientSetupEvent event) {
        CreativeCoreClient.registerClientConfig(MODID);
        MinecraftForge.EVENT_BUS.register(new ReviveEventClient());
    }

    private void init(final FMLCommonSetupEvent event) {
        NETWORK.registerType(ReviveUpdatePacket.class, ReviveUpdatePacket::new);
        NETWORK.registerType(HelperPacket.class, HelperPacket::new);
        NETWORK.registerType(GiveUpPacket.class, GiveUpPacket::new);

        CreativeConfigRegistry.ROOT.registerValue(MODID, CONFIG = new PlayerReviveConfig());
        MinecraftForge.EVENT_BUS.register(new ReviveEventServer());
    }

    private void registerCaps(RegisterCapabilitiesEvent event) {
        event.register(IBleeding.class);
    }

    private void serverStarting(final RegisterCommandsEvent event) {
        event.getDispatcher().register(Commands.literal("revive").requires(x -> x.hasPermission(2)).then(Commands.argument("players", EntityArgument.players()).executes(x -> {
            Collection<ServerPlayer> players = EntityArgument.getPlayers(x, "players");
            for (ServerPlayer player : players)
                if (PlayerReviveServer.getBleeding(player).isBleeding())
                    PlayerReviveServer.revive(player);
            return 0;
        })));
    }

}

package team.creative.playerrevive.api;

import java.util.List;

import com.google.common.collect.Lists;

import net.minecraft.world.damagesource.CombatEntry;
import net.minecraft.world.damagesource.CombatTracker;
import team.creative.playerrevive.mixin.CombatTrackerAccessor;

public class CombatTrackerClone {

    private final List<CombatEntry> combatEntries = Lists.<CombatEntry>newArrayList();
    private int lastDamageTime;
    private int combatStartTime;
    private int combatEndTime;
    private boolean inCombat;
    private boolean takingDamage;

    public CombatTrackerClone(CombatTracker tracker) {
        CombatTrackerAccessor ac = (CombatTrackerAccessor) tracker;
        combatEntries.addAll(ac.getEntries());
        lastDamageTime = ac.getLastDamageTime();
        combatStartTime = ac.getCombatStartTime();
        combatEndTime = ac.getCombatEndTime();
        inCombat = ac.getInCombat();
        takingDamage = ac.getTakingDamage();
    }

    public void overwriteTracker(CombatTracker tracker) {
        CombatTrackerAccessor ac = (CombatTrackerAccessor) tracker;
        List<CombatEntry> entries = ac.getEntries();
        entries.clear();
        entries.addAll(combatEntries);
        ac.setLastDamageTime(lastDamageTime);
        ac.setCombatStartTime(combatStartTime);
        ac.setCombatEndTime(combatEndTime);
        ac.setInCombat(inCombat);
        ac.setTakingDamage(takingDamage);
    }

}

package team.creative.playerrevive.cap;

import java.util.ArrayList;
import java.util.Iterator;
import java.util.List;

import net.minecraft.core.RegistryAccess;
import net.minecraft.core.registries.Registries;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.damagesource.DamageSource;
import net.minecraft.world.entity.Pose;
import net.minecraft.world.entity.player.Player;
import team.creative.playerrevive.PlayerRevive;
import team.creative.playerrevive.api.CombatTrackerClone;
import team.creative.playerrevive.api.IBleeding;
import team.creative.playerrevive.packet.HelperPacket;

public class Bleeding implements IBleeding {

    private boolean bleeding;
    private float progress;
    private int timeLeft;
    private int downedTime;

    private DamageSource lastSource;
    private CombatTrackerClone trackerClone;
    private boolean itemConsumed = false;

    public final List<Player> revivingPlayers = new ArrayList<>();

    public Bleeding() {}

    @Override
    public void tick(Player player) {
        if (player.getPose() != Pose.SWIMMING)
            player.setForcedPose(Pose.SWIMMING);
        for (Iterator<Player> iterator = revivingPlayers.iterator(); iterator.hasNext();) {
            Player helper = iterator.next();
            if (helper.distanceTo(player) > PlayerRevive.CONFIG.revive.maxDistance) {
                PlayerRevive.NETWORK.sendToClient(new HelperPacket(null, false), (ServerPlayer) helper);
                iterator.remove();
            }
        }
        //player.setPose(Pose.SWIMMING);
        if (revivingPlayers.isEmpty() || !PlayerRevive.CONFIG.revive.haltBleedTime)
            timeLeft--;
        if (revivingPlayers.isEmpty() && PlayerRevive.CONFIG.revive.resetProgress)
            progress = 0;

        progress += revivingPlayers.size() * PlayerRevive.CONFIG.revive.progressPerPlayer;
        downedTime++;

        if (PlayerRevive.CONFIG.revive.exhaustion > 0)
            for (int i = 0; i < revivingPlayers.size(); i++)
                revivingPlayers.get(i).causeFoodExhaustion(PlayerRevive.CONFIG.revive.exhaustion);
    }

    @Override
    public void forceBledOut() {
        bleeding = true;
        timeLeft = 0;
    }

    @Override
    public int downedTime() {
        return downedTime;
    }

    @Override
    public float getProgress() {
        return progress;
    }

    @Override
    public boolean revived() {
        return progress >= PlayerRevive.CONFIG.revive.requiredReviveProgress;
    }

    @Override
    public boolean bledOut() {
        return bleeding && timeLeft <= 0;
    }

    @Override
    public CompoundTag serializeNBT() {
        CompoundTag nbt = new CompoundTag();
        nbt.putInt("timeLeft", timeLeft);
        nbt.putFloat("progress", progress);
        nbt.putBoolean("bleeding", bleeding);
        nbt.putBoolean("consumed", itemConsumed);
        return nbt;
    }

    @Override
    public void deserializeNBT(CompoundTag nbt) {
        timeLeft = nbt.getInt("timeLeft");
        progress = nbt.getFloat("progress");
        bleeding = nbt.getBoolean("bleeding");
        itemConsumed = nbt.getBoolean("consumed");
    }

    @Override
    public boolean isBleeding() {
        return bleeding;
    }

    @Override
    public void knockOut(Player player, DamageSource source) {
        this.bleeding = true;
        this.progress = 0;
        this.downedTime = 0;
        this.timeLeft = PlayerRevive.CONFIG.bleeding.bleedTime;
        this.lastSource = source;
        this.trackerClone = new CombatTrackerClone(player.getCombatTracker());
    }

    @Override
    public void revive() {
        this.bleeding = false;
        this.progress = 0;
        this.timeLeft = 0;
        this.downedTime = 0;
        this.lastSource = null;
        this.trackerClone = null;
        this.itemConsumed = false;
    }

    @Override
    public int timeLeft() {
        return timeLeft;
    }

    @Override
    public List<Player> revivingPlayers() {
        return revivingPlayers;
    }

    @Override
    public CombatTrackerClone getTrackerClone() {
        return trackerClone;
    }

    @Override
    public DamageSource getSource(RegistryAccess access) {
        if (lastSource != null)
            return lastSource;
        return new DamageSource(access.registryOrThrow(Registries.DAMAGE_TYPE).getHolderOrThrow(PlayerRevive.BLED_TO_DEATH));
    }

    @Override
    public boolean isItemConsumed() {
        return itemConsumed;
    }

    @Override
    public void setItemConsumed() {
        itemConsumed = true;
    }

}

package team.creative.playerrevive.mixin;

import org.spongepowered.asm.mixin.Mixin;
import org.spongepowered.asm.mixin.injection.At;
import org.spongepowered.asm.mixin.injection.Inject;
import org.spongepowered.asm.mixin.injection.callback.CallbackInfoReturnable;

import net.minecraft.world.entity.EntityType;
import net.minecraft.world.entity.LivingEntity;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.level.Level;
import team.creative.playerrevive.PlayerRevive;
import team.creative.playerrevive.api.IBleeding;
import team.creative.playerrevive.server.PlayerReviveServer;

@Mixin(Player.class)
public abstract class PlayerMixin extends LivingEntity {

    protected PlayerMixin(EntityType<? extends LivingEntity> p_20966_, Level p_20967_) {
        super(p_20966_, p_20967_);
    }

    @Inject(at = @At("HEAD"), method = "Lnet/minecraft/world/entity/player/Player;canBeSeenAsEnemy()Z", cancellable = true)
    public void isBleeding(CallbackInfoReturnable<Boolean> cir) {
        IBleeding bleeding = PlayerReviveServer.getBleeding((Player) (Object) this);
        if (bleeding.isBleeding() && (bleeding.downedTime() <= PlayerRevive.CONFIG.bleeding.initialDamageCooldown || PlayerRevive.CONFIG.bleeding.disableMobDamage))
            cir.setReturnValue(false);
    }

    @Override
    public boolean isPushable() {
        if (super.isPushable()) {
            if (PlayerReviveServer.getBleeding((Player) (Object) this).isBleeding() && !PlayerRevive.CONFIG.bleeding.canBePushed)
                return false;
            return true;
        }
        return false;
    }

}

package team.creative.playerrevive.mixin;

import org.spongepowered.asm.mixin.Mixin;
import org.spongepowered.asm.mixin.injection.At;
import org.spongepowered.asm.mixin.injection.Inject;
import org.spongepowered.asm.mixin.injection.callback.CallbackInfoReturnable;

import net.minecraft.server.level.ServerPlayer;
import team.creative.playerrevive.PlayerRevive;
import team.creative.playerrevive.server.PlayerReviveServer;

@Mixin(ServerPlayer.class)
public class ServerPlayerMixin {

    @Inject(method = "getPermissionLevel()I", at = @At("HEAD"), require = 1, cancellable = true)
    public void getPermissionLevel(CallbackInfoReturnable<Integer> callback) {
        if (PlayerRevive.CONFIG.bleeding.changePermissionLevel && PlayerReviveServer.isBleeding((ServerPlayer) (Object) this))
            callback.setReturnValue(PlayerRevive.CONFIG.bleeding.permissionLevel);
    }

}

package team.creative.playerrevive.packet;

import java.util.UUID;

import net.minecraft.client.Minecraft;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.entity.Pose;
